// Reopen the disposable synthetic project saved by the native workflow.
(() => {
 if(location.hostname!=='127.0.0.1'||window.__ampAutomationReopen)return;window.__ampAutomationReopen=true;
 const wait=async(fn,label)=>{const end=Date.now()+30000;while(Date.now()<end){if(await fn())return;await new Promise(r=>setTimeout(r,50))}throw Error('Timed out: '+label)};
 const read=async name=>{for(let i=0;;i++){try{const r=await fetch('/api/'+name,{cache:'no-store'});if(!r.ok)throw Error(name+': '+r.status);return await r.json()}catch(e){if(!(e instanceof TypeError)||i>=4)throw e;await new Promise(r=>setTimeout(r,100))}}};
 (async()=>{await wait(()=>window.__gosx?.ready&&document.querySelector('#studio-shell[data-shell-actions=ready]'),'Studio');const audio=await read('audio/config'),state=await read('state');if(audio.options.inputEnabled||!audio.options.monitorMuted)throw Error('input was enabled on restart');if(!/automate guitar\.amp_drive\s*\{/.test(state.source)||!state.source.includes('0.45'))throw Error('saved amp movement missing on reopen');const catalog=(await read('params')).addresses;if(!catalog.some(a=>a.address==='guitar.amp_drive'))throw Error('amp control missing on reopen');return {type:'cicada-native-smoke',ok:true,checks:['reopened project retains the recorded track amp curve','amp parameter remains available','input disabled and monitoring muted'],physicalAudioVerified:false,microphoneOpened:false}})().catch(e=>({type:'cicada-native-smoke',ok:false,error:String(e)+'\n'+String(e.stack||'')})).then(r=>window.chrome.webview.postMessage(JSON.stringify(r)));
})();
